const SCHEMA_SQL = `
CREATE TABLE IF NOT EXISTS riders (
  rider_id VARCHAR(64) PRIMARY KEY,
  name VARCHAR(160) NOT NULL,
  city VARCHAR(120) NOT NULL,
  joined_on DATE NOT NULL
);
CREATE TABLE IF NOT EXISTS trips (
