export function appendInvestigationContext(
  state: { issues: Record<string, unknown>[]; [key: string]: unknown },
  outcomes: ClaimOutcome[],
): typeof state {
  if (outcomes.length === 0) return state;
  const byIssue = new Map(outcomes.map((item) => [item.issue_id, item]));
  return {
    ...state,
    issues: state.issues.map((issue) => {
      const result = typeof issue.issue_id === "string" ? byIssue.get(issue.issue_id) : undefined;
      return result ? { ...issue, investigation: result } : issue;
    }),
  };
}

