const r = await tools.exec_command({cmd:"npm run build && node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { decideClaimPaths } from './dist/application/decisions.js';

class FakePool {
  slots = new Map();
  claims = new Map();
  ops = [];
  async query(sql, params = []) {
    const q = sql.replace(/\s+/g, ' ').trim();
    if (q.includes('INSERT INTO claim_decisions')) {
      const [rider, fp, messageId, latest] = params;
      const key = `${rider}:${fp}`;
      const row = this.claims.get(key);
